-- Replaces stock illustration photos (images.unsplash.com) with real product photos.
-- Generated from catalog-real-product-images.csv (sources recorded there). Idempotent: safe to re-run
-- after a catalog re-import. Prebuilt PCs use the real photos of their own case, GPU and CPU.
BEGIN;

CREATE TEMP TABLE real_images (model_code TEXT, sort_order INT, image_url TEXT, alt_text TEXT) ON COMMIT DROP;

-- The new photo becomes the only primary image of each product it is added to.
UPDATE product_images i SET is_primary = FALSE
FROM products p
WHERE i.product_id = p.product_id AND i.is_primary
  AND p.model_code IN (SELECT model_code FROM real_images)
  AND i.image_url NOT IN (SELECT image_url FROM real_images r WHERE r.model_code = p.model_code AND r.sort_order = 0);

-- Only products that receive a real photo lose their stock illustrations.
DELETE FROM product_images i
USING products p
WHERE i.product_id = p.product_id
  AND split_part(i.image_url, '/', 3) = 'images.unsplash.com'
  AND p.model_code IN (SELECT model_code FROM real_images);

SELECT p.product_id, r.image_url, r.alt_text, r.sort_order = 0, r.sort_order, 'IMAGE'
FROM real_images r
JOIN products p ON p.model_code = r.model_code
WHERE NOT EXISTS (SELECT 1 FROM product_images x WHERE x.product_id = p.product_id AND x.image_url = r.image_url);

UPDATE product_images i SET is_primary = TRUE, sort_order = 0
FROM real_images r JOIN products p ON p.model_code = r.model_code
WHERE i.product_id = p.product_id AND i.image_url = r.image_url AND r.sort_order = 0;

-- Any product that has a real photo keeps no stock illustrations in its gallery either.
DELETE FROM product_images i
WHERE split_part(i.image_url, '/', 3) = 'images.unsplash.com'
  AND EXISTS (SELECT 1 FROM product_images r
              WHERE r.product_id = i.product_id AND split_part(r.image_url, '/', 3) <> 'images.unsplash.com');

-- A product whose primary photo is a known-broken URL (see the backend's
-- catalog-unavailable-image-urls.txt) gets its first working photo as primary instead.
CREATE TEMP TABLE broken_images (image_url TEXT PRIMARY KEY) ON COMMIT DROP;

WITH replacement AS (
  SELECT DISTINCT ON (i.product_id) i.product_id, i.image_id
  FROM product_images i
  WHERE i.image_url NOT IN (SELECT image_url FROM broken_images) AND i.media_type = 'IMAGE'
    AND EXISTS (SELECT 1 FROM product_images p WHERE p.product_id = i.product_id AND p.is_primary
                AND p.image_url IN (SELECT image_url FROM broken_images))
  ORDER BY i.product_id, i.sort_order, i.image_id
)
UPDATE product_images i SET is_primary = (i.image_id = r.image_id)
FROM replacement r WHERE i.product_id = r.product_id;

COMMIT;
